function getPixivUid() {
    // cache.delete("pixiv:uid")
    let uid = getFromCache("pixiv:uid")
    if (!uid && isLogin()) {
        let html = java.ajax("https://www.pixiv.net/")
        uid = html.match(/user_id:'(\d+)'/)[1]
        putInCache("pixiv:uid", uid)
    }
    return uid
}

